        #region Deployment

        /// <summary>
        /// Trading pair deployment procceeds once this contract receive the deployFee in GAS from users.
        /// The deployFee stays in the factory and is controlled by the Setter via Withdraw.
        /// </summary>
        public static void OnNEP17Payment(UInt160 from, BigInteger amount, object[] data)
        {
            Assert(data.Length == 2, "Invalid Data.");
            Assert(Runtime.CallingScriptHash == GAS.Hash, "Wrong Calling Scripthash.");
            Assert(amount == GetDeployFee(), "Wrong Deploy Fee.");
            Assert(from.IsValid && !from.IsZero, "Invalid Sender.");

            DeployPair(
                (UInt160)data[0],
                (UInt160)data[1]);
        }

        /// <summary>
        /// Deploy a pair contract, only can be called by users with GAS and the fee, the pair contract will 
        /// be deployed by Factory and initialized by Router.
