            StorePair(tokenA, tokenB, pairContract.Hash);
        }

        /// <summary>
        /// Store the pair address with tokenA and tokenB, and trigger event for front-end to listen.
        /// </summary>
        private static void StorePair(UInt160 tokenA, UInt160 tokenB, UInt160 pairHash)
        {
            Assert(tokenA.IsAddress() && tokenB.IsAddress(), "Invalid Address.");
            Assert(tokenA != tokenB, "Identical Address.", tokenA);
            var key = GetPairKey(tokenA, tokenB);
            var value = StorageGet(key);
            Assert(value == null || value.Length == 0, "Exchange Already Existed.");

            StoragePut(key, pairHash);
            onStorePair(tokenA, tokenB, pairHash);
        }
        #endregion

        #region PairHash

        /// <summary>
        /// Get pair address by tokenA and tokenB, return null if not exist.
        /// </summary>
        [Safe]
        public static ByteString GetPairHash(UInt160 tokenA, UInt160 tokenB)
        {
            Assert(tokenA != tokenB, "Identical Address", tokenA);
            return StorageGet(GetPairKey(tokenA, tokenB));
        }

        [Safe]
        public static TradingPair[] GetAllPairsHash()
        {
            var iterator = (Iterator<KeyValue>)StorageFind(PAIR_PREFIX);
            var result = new TradingPair[0];
            while (iterator.Next())
            {
                var keyValue = iterator.Value;
                if (keyValue.Value != null)
                {
                    var pairHash = keyValue.Value;
                    var tokenA = keyValue.Key.Take(20);
                    var tokenB = keyValue.Key.Last(20);
                    var item = new TradingPair()
                    {
                        TokenA = (UInt160)tokenA,
                        TokenB = (UInt160)tokenB,
                        Pair = pairHash,
                    };
                    Append(result, item);
                }
            }
            return result;
        }

        /// <summary>
        /// Get the storage key for pair, tokenA and tokenB order does not matter.
        /// </summary>
        private static byte[] GetPairKey(UInt160 tokenA, UInt160 tokenB)
        {
            return tokenA.ToUInteger() < tokenB.ToUInteger()
                ? PAIR_PREFIX.Concat(tokenA).Concat(tokenB)
                : PAIR_PREFIX.Concat(tokenB).Concat(tokenA);
        }
        #endregion
    }
